-- 2. OPUS — SAT_AGREEMENT_COMMERCIAL_TERMS   [Implemented]
-- standard satellite, automate_dv.sat; PK AGREEMENT_HKEY; 1 RECORD_SOURCE group(s):
-- OPUS_BJAZ_INTERMEDIARY [1 col(s)]. TRIMMED / BLANK_TO_NULL on trim / nullif columns =
-- documented exception (staging trim rule retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct AGREEMENT_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AGREEMENT_COMMERCIAL_TERMS
     where RECORD_SOURCE = 'OPUS_BJAZ_INTERMEDIARY'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select AGREEMENT_HKEY as hkey,
           to_varchar(COMMISSIONSTRUCTURE) as COMMISSIONSTRUCTURE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AGREEMENT_COMMERCIAL_TERMS
     where RECORD_SOURCE = 'OPUS_BJAZ_INTERMEDIARY'
       and AGREEMENT_HKEY in (select hkey from s1)
    qualify rank() over (partition by AGREEMENT_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_partner__bjaz_intermediary
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_AGREEMENT|' || ((nullif(trim("INTERMEDIARY_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
               ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
               to_varchar("TYPE_OF_COMM_ARR") as COMMISSIONSTRUCTURE
          from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_INTERMEDIARY
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'COMMISSIONSTRUCTURE' as column_name, 'TYPE_OF_COMM_ARR' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.COMMISSIONSTRUCTURE, e.COMMISSIONSTRUCTURE) then 0
                when c.COMMISSIONSTRUCTURE is null and nullif(trim(e.COMMISSIONSTRUCTURE), '') is null then 1
                when c.COMMISSIONSTRUCTURE = trim(e.COMMISSIONSTRUCTURE) then 2
                when upper(c.COMMISSIONSTRUCTURE) = upper(trim(e.COMMISSIONSTRUCTURE)) then 3
                when try_to_decimal(c.COMMISSIONSTRUCTURE, 38, 10) = try_to_decimal(trim(e.COMMISSIONSTRUCTURE), 38, 10) then 4
                when try_to_timestamp_ntz(c.COMMISSIONSTRUCTURE) = try_to_timestamp_ntz(trim(e.COMMISSIONSTRUCTURE)) then 5
                when length(c.COMMISSIONSTRUCTURE) < length(e.COMMISSIONSTRUCTURE) and startswith(e.COMMISSIONSTRUCTURE, c.COMMISSIONSTRUCTURE) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.COMMISSIONSTRUCTURE
)
select 'OPUS' as project, 'SAT_AGREEMENT_COMMERCIAL_TERMS' as satellite, 'OPUS_BJAZ_INTERMEDIARY' as record_source,
       column_name, raw_column, model_rule, count(*) as keys_compared,
       count_if(src_rows > 0 and cls = 0) as exact,
       count_if(src_rows > 0 and cls = 1) as blank_to_null,
       count_if(src_rows > 0 and cls = 2) as trimmed,
       count_if(src_rows > 0 and cls = 3) as case_changed,
       count_if(src_rows > 0 and cls = 4) as number_format_changed,
       count_if(src_rows > 0 and cls = 5) as date_format_changed,
       count_if(src_rows > 0 and cls = 6) as truncated,
       count_if(src_rows > 0 and cls = 7) as value_differs,
       count_if(src_rows = 0) as no_source_row,
       iff(truncated = 0
           and (value_differs = 0 or any_value(r_conv))
           and (trimmed = 0 or any_value(r_trim))
           and (blank_to_null = 0 or any_value(r_nullif))
           and (case_changed = 0 or any_value(r_case))
           and (number_format_changed + date_format_changed = 0 or any_value(r_conv)), 'PASS', 'FAIL') as status
  from r1
 group by column_name, raw_column, model_rule
order by record_source, column_name;



