               to_varchar("IP_NO") as ROLE_SEQUENCE
          from BAGIC_PREPROD_CURATED_DB.UTILS.CLM_INTERESTED_PARTIES
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey, cdk_1, cdk_2 order by ldts desc) = 1
),
r1 as (
    select 'PARTY_ROLE_TYPE' as column_name, 'IP_TYPE' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.PARTY_ROLE_TYPE, e.PARTY_ROLE_TYPE) then 0
                when c.PARTY_ROLE_TYPE is null and nullif(trim(e.PARTY_ROLE_TYPE), '') is null then 1
