-- 14. OPUS — SAT_LNK_POLICY_PARTY_ROLE   [Implemented]
-- standard satellite, automate_dv.ma_sat; PK POLICY_PARTY_HKEY, child key ROLE_SEQUENCE;
-- 1 RECORD_SOURCE group(s): OPUS_OCP_INTERESTED_PARTIES [1 col(s)]. Multi-active:
-- compared per (key, child key); latest = max LOAD_DATETIME per member. TRIMMED /
-- BLANK_TO_NULL on trim / nullif columns = documented exception (staging trim rule
-- retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct POLICY_PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_LNK_POLICY_PARTY_ROLE
     where RECORD_SOURCE = 'OPUS_OCP_INTERESTED_PARTIES'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select POLICY_PARTY_HKEY as hkey,
           to_varchar(ROLE_SEQUENCE) as cdk_1,
           to_varchar(ROLE_SEQUENCE) as ROLE_SEQUENCE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_LNK_POLICY_PARTY_ROLE
     where RECORD_SOURCE = 'OPUS_OCP_INTERESTED_PARTIES'
       and POLICY_PARTY_HKEY in (select hkey from s1)
    qualify rank() over (partition by POLICY_PARTY_HKEY, ROLE_SEQUENCE order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_partner__ocp_interested_parties
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_POLICY_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), '')) || '|' || (nullif(trim("CONTRACT_ID"::varchar), '')) AS VARCHAR))), '')) as hkey,
               to_varchar(("IP_NO"::number)) as cdk_1,
               ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
               to_varchar("IP_NO") as ROLE_SEQUENCE
          from BAGIC_PREPROD_CURATED_DB.UTILS.OCP_INTERESTED_PARTIES
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey, cdk_1 order by ldts desc) = 1
),
r1 as (
    select 'ROLE_SEQUENCE' as column_name, 'IP_NO' as raw_column, 'conv' as model_rule,
           false as r_trim, false as r_nullif, false as r_case, true as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.ROLE_SEQUENCE, e.ROLE_SEQUENCE) then 0
                when c.ROLE_SEQUENCE is null and nullif(trim(e.ROLE_SEQUENCE), '') is null then 1
                when c.ROLE_SEQUENCE = trim(e.ROLE_SEQUENCE) then 2
                when upper(c.ROLE_SEQUENCE) = upper(trim(e.ROLE_SEQUENCE)) then 3
                when try_to_decimal(c.ROLE_SEQUENCE, 38, 10) = try_to_decimal(trim(e.ROLE_SEQUENCE), 38, 10) then 4
                when try_to_timestamp_ntz(c.ROLE_SEQUENCE) = try_to_timestamp_ntz(trim(e.ROLE_SEQUENCE)) then 5
                when length(c.ROLE_SEQUENCE) < length(e.ROLE_SEQUENCE) and startswith(e.ROLE_SEQUENCE, c.ROLE_SEQUENCE) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey and equal_null(e.cdk_1, c.cdk_1)
     group by c.hkey, c.cdk_1, c.ROLE_SEQUENCE
)
