----------------------------------------------------------------------------------------
-- 18. OPUS — SAT_LNK_ROLE_PROVIDER   [Implemented]
-- standard satellite, sat_multi_source; PK PARTY_HKEY; 2 RECORD_SOURCE group(s):
-- OPUS_BJAZ_HM_HOSPITAL_MASTER [5 col(s)], OPUS_CLM_SUPPLIERS [5 col(s)]. TRIMMED /
-- BLANK_TO_NULL on trim / nullif columns = documented exception (staging trim rule
-- retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_LNK_ROLE_PROVIDER
     where RECORD_SOURCE = 'OPUS_BJAZ_HM_HOSPITAL_MASTER'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(EMPANELMENT_DATE) as EMPANELMENT_DATE,
           to_varchar(SPECIALISATION) as SPECIALISATION,
           to_varchar(PROVIDER_TYPE) as PROVIDER_TYPE,
           to_varchar(NETWORK_INDICATOR) as NETWORK_INDICATOR,
           to_varchar(PREFERRED_PROVIDER_INDICATOR) as PREFERRED_PROVIDER_INDICATOR
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_LNK_ROLE_PROVIDER
     where RECORD_SOURCE = 'OPUS_BJAZ_HM_HOSPITAL_MASTER'
       and PARTY_HKEY in (select hkey from s1)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_partner__bjaz_hm_hospital_master
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim("HOSID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
               ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
               to_varchar("DATE_OF_SUP") as EMPANELMENT_DATE,
               to_varchar("HOSP_SPECIALITY") as SPECIALISATION,
               to_varchar("HOSP_TYPE") as PROVIDER_TYPE,
               to_varchar("HOS_STATUS") as NETWORK_INDICATOR,
               to_varchar("PREFERRED_FLAG") as PREFERRED_PROVIDER_INDICATOR
          from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_HOSPITAL_MASTER
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'EMPANELMENT_DATE' as column_name, 'DATE_OF_SUP' as raw_column, 'conv' as model_rule,
           false as r_trim, false as r_nullif, false as r_case, true as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.EMPANELMENT_DATE, e.EMPANELMENT_DATE) then 0
                when c.EMPANELMENT_DATE is null and nullif(trim(e.EMPANELMENT_DATE), '') is null then 1
                when c.EMPANELMENT_DATE = trim(e.EMPANELMENT_DATE) then 2
                when upper(c.EMPANELMENT_DATE) = upper(trim(e.EMPANELMENT_DATE)) then 3
                when try_to_decimal(c.EMPANELMENT_DATE, 38, 10) = try_to_decimal(trim(e.EMPANELMENT_DATE), 38, 10) then 4
                when try_to_timestamp_ntz(c.EMPANELMENT_DATE) = try_to_timestamp_ntz(trim(e.EMPANELMENT_DATE)) then 5
                when length(c.EMPANELMENT_DATE) < length(e.EMPANELMENT_DATE) and startswith(e.EMPANELMENT_DATE, c.EMPANELMENT_DATE) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.EMPANELMENT_DATE
    union all
    select 'SPECIALISATION' as column_name, 'HOSP_SPECIALITY' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.SPECIALISATION, e.SPECIALISATION) then 0
                when c.SPECIALISATION is null and nullif(trim(e.SPECIALISATION), '') is null then 1
                when c.SPECIALISATION = trim(e.SPECIALISATION) then 2
                when upper(c.SPECIALISATION) = upper(trim(e.SPECIALISATION)) then 3
                when try_to_decimal(c.SPECIALISATION, 38, 10) = try_to_decimal(trim(e.SPECIALISATION), 38, 10) then 4
                when try_to_timestamp_ntz(c.SPECIALISATION) = try_to_timestamp_ntz(trim(e.SPECIALISATION)) then 5
                when length(c.SPECIALISATION) < length(e.SPECIALISATION) and startswith(e.SPECIALISATION, c.SPECIALISATION) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.SPECIALISATION
    union all
    select 'PROVIDER_TYPE' as column_name, 'HOSP_TYPE' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.PROVIDER_TYPE, e.PROVIDER_TYPE) then 0
                when c.PROVIDER_TYPE is null and nullif(trim(e.PROVIDER_TYPE), '') is null then 1
                when c.PROVIDER_TYPE = trim(e.PROVIDER_TYPE) then 2
                when upper(c.PROVIDER_TYPE) = upper(trim(e.PROVIDER_TYPE)) then 3
                when try_to_decimal(c.PROVIDER_TYPE, 38, 10) = try_to_decimal(trim(e.PROVIDER_TYPE), 38, 10) then 4
                when try_to_timestamp_ntz(c.PROVIDER_TYPE) = try_to_timestamp_ntz(trim(e.PROVIDER_TYPE)) then 5
                when length(c.PROVIDER_TYPE) < length(e.PROVIDER_TYPE) and startswith(e.PROVIDER_TYPE, c.PROVIDER_TYPE) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.PROVIDER_TYPE
    union all
    select 'NETWORK_INDICATOR' as column_name, 'HOS_STATUS' as raw_column, 'conv' as model_rule,
           false as r_trim, false as r_nullif, false as r_case, true as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.NETWORK_INDICATOR, e.NETWORK_INDICATOR) then 0
                when c.NETWORK_INDICATOR is null and nullif(trim(e.NETWORK_INDICATOR), '') is null then 1
                when c.NETWORK_INDICATOR = trim(e.NETWORK_INDICATOR) then 2
                when upper(c.NETWORK_INDICATOR) = upper(trim(e.NETWORK_INDICATOR)) then 3
                when try_to_decimal(c.NETWORK_INDICATOR, 38, 10) = try_to_decimal(trim(e.NETWORK_INDICATOR), 38, 10) then 4
                when try_to_timestamp_ntz(c.NETWORK_INDICATOR) = try_to_timestamp_ntz(trim(e.NETWORK_INDICATOR)) then 5
                when length(c.NETWORK_INDICATOR) < length(e.NETWORK_INDICATOR) and startswith(e.NETWORK_INDICATOR, c.NETWORK_INDICATOR) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.NETWORK_INDICATOR
    union all
