-- 36. OPUS — SAT_POLICY_CERTIFICATE   [Implemented]
-- standard satellite, sat_multi_source; PK POLICY_HKEY; 3 RECORD_SOURCE group(s):
-- OPUS_BA_HCP_DT_MEM [1 col(s)], OPUS_BJAZ_CTNGY_PA_MEM_DTLS [1 col(s)],
-- OPUS_BJAZ_HM_MEMBER_DTLS [1 col(s)]. TRIMMED / BLANK_TO_NULL on trim / nullif columns
-- = documented exception (staging trim rule retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct POLICY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_CERTIFICATE
     where RECORD_SOURCE = 'OPUS_BA_HCP_DT_MEM'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select POLICY_HKEY as hkey,
           to_varchar(MEMBERSTATUS) as MEMBERSTATUS
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_CERTIFICATE
     where RECORD_SOURCE = 'OPUS_BA_HCP_DT_MEM'
       and POLICY_HKEY in (select hkey from s1)
    qualify rank() over (partition by POLICY_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_partner__ba_hcp_dt_mem
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || ((nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
               ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
               to_varchar("MEM_STATUS") as MEMBERSTATUS
          from BAGIC_PREPROD_CURATED_DB.UTILS.BA_HCP_DT_MEM
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'MEMBERSTATUS' as column_name, 'MEM_STATUS' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.MEMBERSTATUS, e.MEMBERSTATUS) then 0
                when c.MEMBERSTATUS is null and nullif(trim(e.MEMBERSTATUS), '') is null then 1
                when c.MEMBERSTATUS = trim(e.MEMBERSTATUS) then 2
                when upper(c.MEMBERSTATUS) = upper(trim(e.MEMBERSTATUS)) then 3
                when try_to_decimal(c.MEMBERSTATUS, 38, 10) = try_to_decimal(trim(e.MEMBERSTATUS), 38, 10) then 4
                when try_to_timestamp_ntz(c.MEMBERSTATUS) = try_to_timestamp_ntz(trim(e.MEMBERSTATUS)) then 5
                when length(c.MEMBERSTATUS) < length(e.MEMBERSTATUS) and startswith(e.MEMBERSTATUS, c.MEMBERSTATUS) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.MEMBERSTATUS
),
s2 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct POLICY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_CERTIFICATE
