-- 37. OPUS — SAT_POLICY_CLASSIFICATION   [Implemented]
-- standard satellite, ma_sat_multi_source; PK POLICY_HKEY, child key CLASSIFICATIONTYPE;
-- 4 RECORD_SOURCE group(s): OPUS_BJAZ_T_KYC_DETAILS [1 col(s)], OPUS_BJAZ_T_KYC_INCOMING
-- [1 col(s)], OPUS_BJAZ_T_KYC_POA_DOCUMENT [1 col(s)], OPUS_BJAZ_T_KYC_POI_DOCUMENT [1
-- col(s)]. Multi-active: compared per (key, child key); latest = max LOAD_DATETIME per
-- member. TRIMMED / BLANK_TO_NULL on trim / nullif columns = documented exception
-- (staging trim rule retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct POLICY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_CLASSIFICATION
     where RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_DETAILS'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select POLICY_HKEY as hkey,
           to_varchar(CLASSIFICATIONTYPE) as cdk_1,
           to_varchar(CLASSIFICATIONVALUE) as CLASSIFICATIONVALUE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_CLASSIFICATION
     where RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_DETAILS'
       and POLICY_HKEY in (select hkey from s1)
    qualify rank() over (partition by POLICY_HKEY, CLASSIFICATIONTYPE order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_partner__bjaz_t_kyc_details
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (upper(case when upper(trim((nullif(trim("FIELD_TYPE"::varchar), '')))) like 'POLICY%' then trim((nullif(trim("FIELD_VALUE"::varchar), ''))) end)) AS VARCHAR))), '')) as hkey,
               to_varchar('BUSINESS_TYPE') as cdk_1,
               (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as ldts,
               to_varchar("BUSINESS_TYPE") as CLASSIFICATIONVALUE
          from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_DETAILS
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey, cdk_1 order by ldts desc) = 1
),
r1 as (
    select 'CLASSIFICATIONVALUE' as column_name, 'BUSINESS_TYPE' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.CLASSIFICATIONVALUE, e.CLASSIFICATIONVALUE) then 0
                when c.CLASSIFICATIONVALUE is null and nullif(trim(e.CLASSIFICATIONVALUE), '') is null then 1
                when c.CLASSIFICATIONVALUE = trim(e.CLASSIFICATIONVALUE) then 2
                when upper(c.CLASSIFICATIONVALUE) = upper(trim(e.CLASSIFICATIONVALUE)) then 3
                when try_to_decimal(c.CLASSIFICATIONVALUE, 38, 10) = try_to_decimal(trim(e.CLASSIFICATIONVALUE), 38, 10) then 4
                when try_to_timestamp_ntz(c.CLASSIFICATIONVALUE) = try_to_timestamp_ntz(trim(e.CLASSIFICATIONVALUE)) then 5
                when length(c.CLASSIFICATIONVALUE) < length(e.CLASSIFICATIONVALUE) and startswith(e.CLASSIFICATIONVALUE, c.CLASSIFICATIONVALUE) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey and equal_null(e.cdk_1, c.cdk_1)
     group by c.hkey, c.cdk_1, c.CLASSIFICATIONVALUE
),
s2 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct POLICY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_CLASSIFICATION
     where RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_INCOMING'
     order by hkey
     limit 100
),
c2 as (  -- latest satellite row per sampled key
    select POLICY_HKEY as hkey,
           to_varchar(CLASSIFICATIONTYPE) as cdk_1,
           to_varchar(CLASSIFICATIONVALUE) as CLASSIFICATIONVALUE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_CLASSIFICATION
     where RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_INCOMING'
       and POLICY_HKEY in (select hkey from s2)
    qualify rank() over (partition by POLICY_HKEY, CLASSIFICATIONTYPE order by LOAD_DATETIME desc) = 1
),
e2 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_partner__bjaz_t_kyc_incoming
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (case when upper(trim((nullif(trim("FIELD_TYPE"::varchar), '')))) like 'POLICY%' then trim((nullif(trim("FIELD_VALUE"::varchar), ''))) end) AS VARCHAR))), '')) as hkey,
               to_varchar('BUSINESS_TYPE') as cdk_1,
