),
s2 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_LNK_ROLE_PROVIDER
     where RECORD_SOURCE = 'OPUS_BJAZ_HM_HOSPITAL_MASTER'
     order by hkey
     limit 100
),
c2 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(CONTACT_PERSON_DESIGNATION) as CONTACT_PERSON_DESIGNATION,
           to_varchar(CONTACT_PERSON_NAME) as CONTACT_PERSON_NAME,
           to_varchar(DIAGNO_YN) as DIAGNO_YN,
           to_varchar(EMPANEL_DATE) as EMPANEL_DATE,
           to_varchar(HOSP_SPEC_TYPE) as HOSP_SPEC_TYPE,
           to_varchar(NETWORK_TYPE) as NETWORK_TYPE,
           to_varchar(PRIORITY_FLG) as PRIORITY_FLG
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_LNK_ROLE_PROVIDER
     where RECORD_SOURCE = 'OPUS_BJAZ_HM_HOSPITAL_MASTER'
       and PARTY_HKEY in (select hkey from s2)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e2 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_partner__bjaz_hm_hospital_master
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim("HOSID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
               ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
               to_varchar("DESIGNATION") as CONTACT_PERSON_DESIGNATION,
               to_varchar("CONTACT_PERSON") as CONTACT_PERSON_NAME,
               to_varchar("DIAGNO_YN") as DIAGNO_YN,
               to_varchar("EMPANEL_DATE") as EMPANEL_DATE,
               to_varchar("HOSP_SPEC_TYPE") as HOSP_SPEC_TYPE,
               to_varchar("NETWORK_TYPE") as NETWORK_TYPE,
               to_varchar("PRIORITY_FLG") as PRIORITY_FLG
          from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_HOSPITAL_MASTER
      )
     where hkey in (select hkey from s2) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r2 as (
    select 'CONTACT_PERSON_DESIGNATION' as column_name, 'DESIGNATION' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.CONTACT_PERSON_DESIGNATION, e.CONTACT_PERSON_DESIGNATION) then 0
                when c.CONTACT_PERSON_DESIGNATION is null and nullif(trim(e.CONTACT_PERSON_DESIGNATION), '') is null then 1
                when c.CONTACT_PERSON_DESIGNATION = trim(e.CONTACT_PERSON_DESIGNATION) then 2
                when upper(c.CONTACT_PERSON_DESIGNATION) = upper(trim(e.CONTACT_PERSON_DESIGNATION)) then 3
                when try_to_decimal(c.CONTACT_PERSON_DESIGNATION, 38, 10) = try_to_decimal(trim(e.CONTACT_PERSON_DESIGNATION), 38, 10) then 4
                when try_to_timestamp_ntz(c.CONTACT_PERSON_DESIGNATION) = try_to_timestamp_ntz(trim(e.CONTACT_PERSON_DESIGNATION)) then 5
                when length(c.CONTACT_PERSON_DESIGNATION) < length(e.CONTACT_PERSON_DESIGNATION) and startswith(e.CONTACT_PERSON_DESIGNATION, c.CONTACT_PERSON_DESIGNATION) then 6
