        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || ((nullif(trim("ADD_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
               ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
               to_varchar("ADDRESSEE") as CARE_OF_NAME
          from BAGIC_PREPROD_CURATED_DB.UTILS.CP_PARTNERS
      )
     where hkey in (select hkey from s2) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r2 as (
    select 'CARE_OF_NAME' as column_name, 'ADDRESSEE' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.CARE_OF_NAME, e.CARE_OF_NAME) then 0
                when c.CARE_OF_NAME is null and nullif(trim(e.CARE_OF_NAME), '') is null then 1
                when c.CARE_OF_NAME = trim(e.CARE_OF_NAME) then 2
                when upper(c.CARE_OF_NAME) = upper(trim(e.CARE_OF_NAME)) then 3
                when try_to_decimal(c.CARE_OF_NAME, 38, 10) = try_to_decimal(trim(e.CARE_OF_NAME), 38, 10) then 4
                when try_to_timestamp_ntz(c.CARE_OF_NAME) = try_to_timestamp_ntz(trim(e.CARE_OF_NAME)) then 5
                when length(c.CARE_OF_NAME) < length(e.CARE_OF_NAME) and startswith(e.CARE_OF_NAME, c.CARE_OF_NAME) then 6
                else 7 end) as cls
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.CARE_OF_NAME
)
select 'OPUS' as project, 'SAT_AUG_LOCATION' as satellite, 'OPUS_CP_ADDRESSES' as record_source,
       column_name, raw_column, model_rule, count(*) as keys_compared,
       count_if(src_rows > 0 and cls = 0) as exact,
       count_if(src_rows > 0 and cls = 1) as blank_to_null,
       count_if(src_rows > 0 and cls = 2) as trimmed,
       count_if(src_rows > 0 and cls = 3) as case_changed,
       count_if(src_rows > 0 and cls = 4) as number_format_changed,
       count_if(src_rows > 0 and cls = 5) as date_format_changed,
       count_if(src_rows > 0 and cls = 6) as truncated,
       count_if(src_rows > 0 and cls = 7) as value_differs,
       count_if(src_rows = 0) as no_source_row,
       iff(truncated = 0
           and (value_differs = 0 or any_value(r_conv))
           and (trimmed = 0 or any_value(r_trim))
           and (blank_to_null = 0 or any_value(r_nullif))
           and (case_changed = 0 or any_value(r_case))
           and (number_format_changed + date_format_changed = 0 or any_value(r_conv)), 'PASS', 'FAIL') as status
  from r1
 group by column_name, raw_column, model_rule
union all
