-- 59. OPUS — SAT_AUG_PARTY   [Implemented]
-- augmented satellite, sat_multi_source; PK PARTY_HKEY; 10 RECORD_SOURCE group(s):
-- OPUS_AZBJ_PARTNER_EXTN [8 col(s)], OPUS_BJAZ_INTERMEDIARY [3 col(s)],
-- OPUS_BJAZ_EC_MEM_DTLS_EXTN [3 col(s)], OPUS_BJAZ_HCF_MEMBER_DTLS [1 col(s)],
