-- OPUS_BJAZ_HM_MEMBER_DTLS [1 col(s)], OPUS_BJAZ_HM_HOSPITAL_MASTER [3 col(s)]. TRIMMED
-- / BLANK_TO_NULL on trim / nullif columns = documented exception (staging trim rule
-- retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY
     where RECORD_SOURCE = 'OPUS_AZBJ_PARTNER_EXTN'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(ECS_MANDATE_STATUS) as ECS_MANDATE_STATUS,
