----------------------------------------------------------------------------------------
-- 60. OPUS — SAT_AUG_POLICY   [Implemented]
-- augmented satellite, ma_sat_multi_source; PK POLICY_HKEY, child key MEMBER_SEQUENCE; 5
-- RECORD_SOURCE group(s): OPUS_BJAZ_HLT_ENSURE_MEM_DTLS [1 col(s)],
-- OPUS_BJAZ_HM_MEMBER_DTLS [1 col(s)], OPUS_BJAZ_PA_DETL_EXTN [5 col(s)],
-- OPUS_BJAZ_EC_MEM_DTLS_EXTN [1 col(s)], OPUS_BJAZ_SH_MEM_DTLS_EXTN [1 col(s)].
-- Multi-active: compared per (key, child key); latest = max LOAD_DATETIME per member.
-- TRIMMED / BLANK_TO_NULL on trim / nullif columns = documented exception (staging trim
-- rule retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct POLICY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_POLICY
     where RECORD_SOURCE = 'OPUS_BJAZ_HLT_ENSURE_MEM_DTLS'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select POLICY_HKEY as hkey,
           to_varchar(MEMBER_SEQUENCE) as cdk_1,
           to_varchar(PREVIOUS_CUM_AMOUNT) as PREVIOUS_CUM_AMOUNT
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_POLICY
     where RECORD_SOURCE = 'OPUS_BJAZ_HLT_ENSURE_MEM_DTLS'
       and POLICY_HKEY in (select hkey from s1)
    qualify rank() over (partition by POLICY_HKEY, MEMBER_SEQUENCE order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_partner__bjaz_hlt_ensure_mem_dtls
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || ((nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
               to_varchar(("MEMBER_NO"::number)) as cdk_1,
               ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
               to_varchar("PREVIOUS_CUM_AMOUNT") as PREVIOUS_CUM_AMOUNT
          from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HLT_ENSURE_MEM_DTLS
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey, cdk_1 order by ldts desc) = 1
),
r1 as (
    select 'PREVIOUS_CUM_AMOUNT' as column_name, 'PREVIOUS_CUM_AMOUNT' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.PREVIOUS_CUM_AMOUNT, e.PREVIOUS_CUM_AMOUNT) then 0
                when c.PREVIOUS_CUM_AMOUNT is null and nullif(trim(e.PREVIOUS_CUM_AMOUNT), '') is null then 1
                when c.PREVIOUS_CUM_AMOUNT = trim(e.PREVIOUS_CUM_AMOUNT) then 2
                when upper(c.PREVIOUS_CUM_AMOUNT) = upper(trim(e.PREVIOUS_CUM_AMOUNT)) then 3
                when try_to_decimal(c.PREVIOUS_CUM_AMOUNT, 38, 10) = try_to_decimal(trim(e.PREVIOUS_CUM_AMOUNT), 38, 10) then 4
                when try_to_timestamp_ntz(c.PREVIOUS_CUM_AMOUNT) = try_to_timestamp_ntz(trim(e.PREVIOUS_CUM_AMOUNT)) then 5
                when length(c.PREVIOUS_CUM_AMOUNT) < length(e.PREVIOUS_CUM_AMOUNT) and startswith(e.PREVIOUS_CUM_AMOUNT, c.PREVIOUS_CUM_AMOUNT) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey and equal_null(e.cdk_1, c.cdk_1)
     group by c.hkey, c.cdk_1, c.PREVIOUS_CUM_AMOUNT
),
s2 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct POLICY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_POLICY
     where RECORD_SOURCE = 'OPUS_BJAZ_HM_MEMBER_DTLS'
     order by hkey
     limit 100
),
