     where RECORD_SOURCE = 'OPUS_BJAZ_HM_MEMBER_DTLS'
       and POLICY_HKEY in (select hkey from s2)
    qualify rank() over (partition by POLICY_HKEY, MEMBER_SEQUENCE order by LOAD_DATETIME desc) = 1
),
