),
s5 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct POLICY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_POLICY
     where RECORD_SOURCE = 'OPUS_BJAZ_SH_MEM_DTLS_EXTN'
     order by hkey
     limit 100
),
c5 as (  -- latest satellite row per sampled key
    select POLICY_HKEY as hkey,
           to_varchar(MEMBER_SEQUENCE) as cdk_1,
           to_varchar(INCEPTION_DATE) as INCEPTION_DATE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_POLICY
     where RECORD_SOURCE = 'OPUS_BJAZ_SH_MEM_DTLS_EXTN'
       and POLICY_HKEY in (select hkey from s5)
    qualify rank() over (partition by POLICY_HKEY, MEMBER_SEQUENCE order by LOAD_DATETIME desc) = 1
),
e5 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_partner__bjaz_sh_mem_dtls_extn
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || ((nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
               to_varchar(("MEMBER_NO"::number)) as cdk_1,
               ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
               to_varchar("INCEPTION_DATE") as INCEPTION_DATE
          from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN
      )
     where hkey in (select hkey from s5) and ldts is not null
    qualify rank() over (partition by hkey, cdk_1 order by ldts desc) = 1
),
r5 as (
    select 'INCEPTION_DATE' as column_name, 'INCEPTION_DATE' as raw_column, 'conv' as model_rule,
           false as r_trim, false as r_nullif, false as r_case, true as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.INCEPTION_DATE, e.INCEPTION_DATE) then 0
                when c.INCEPTION_DATE is null and nullif(trim(e.INCEPTION_DATE), '') is null then 1
                when c.INCEPTION_DATE = trim(e.INCEPTION_DATE) then 2
                when upper(c.INCEPTION_DATE) = upper(trim(e.INCEPTION_DATE)) then 3
                when try_to_decimal(c.INCEPTION_DATE, 38, 10) = try_to_decimal(trim(e.INCEPTION_DATE), 38, 10) then 4
                when try_to_timestamp_ntz(c.INCEPTION_DATE) = try_to_timestamp_ntz(trim(e.INCEPTION_DATE)) then 5
                when length(c.INCEPTION_DATE) < length(e.INCEPTION_DATE) and startswith(e.INCEPTION_DATE, c.INCEPTION_DATE) then 6
                else 7 end) as cls
      from c5 c left join e5 e on e.hkey = c.hkey and equal_null(e.cdk_1, c.cdk_1)
     group by c.hkey, c.cdk_1, c.INCEPTION_DATE
)
select 'OPUS' as project, 'SAT_AUG_POLICY' as satellite, 'OPUS_BJAZ_HLT_ENSURE_MEM_DTLS' as record_source,
       column_name, raw_column, model_rule, count(*) as keys_compared,
       count_if(src_rows > 0 and cls = 0) as exact,
       count_if(src_rows > 0 and cls = 1) as blank_to_null,
       count_if(src_rows > 0 and cls = 2) as trimmed,
       count_if(src_rows > 0 and cls = 3) as case_changed,
       count_if(src_rows > 0 and cls = 4) as number_format_changed,
       count_if(src_rows > 0 and cls = 5) as date_format_changed,
       count_if(src_rows > 0 and cls = 6) as truncated,
       count_if(src_rows > 0 and cls = 7) as value_differs,
       count_if(src_rows = 0) as no_source_row,
       iff(truncated = 0
           and (value_differs = 0 or any_value(r_conv))
           and (trimmed = 0 or any_value(r_trim))
           and (blank_to_null = 0 or any_value(r_nullif))
           and (case_changed = 0 or any_value(r_case))
           and (number_format_changed + date_format_changed = 0 or any_value(r_conv)), 'PASS', 'FAIL') as status
  from r1
 group by column_name, raw_column, model_rule
union all
